 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    boxes = {}
    for color in range(1, 10):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not pts:
            continue
        r0 = min(r for r,c in pts); r1 = max(r for r,c in pts)
        c0 = min(c for r,c in pts); c1 = max(c for r,c in pts)
        # Candidate frame: its complete bounding-box perimeter is this color.
        if all(grid[r][c] == color for r in range(r0, r1+1) for c in range(c0, c1+1)
               if r in (r0,r1) or c in (c0,c1)):
            boxes[color] = (r0,r1,c0,c1)
    if not boxes:
        return out
    sizes = Counter((r1-r0+1, c1-c0+1) for r0,r1,c0,c1 in boxes.values())
    main_size = max(sizes, key=lambda s: (sizes[s], s[0]*s[1]))
    group = {color: box for color,box in boxes.items()
             if (box[1]-box[0]+1, box[3]-box[2]+1) == main_size}
    # Locate the unique nonempty interior motif within the repeated-size frames.
    motif = None
    for color, (r0,r1,c0,c1) in group.items():
        cells = [(r-r0, c-c0) for r in range(r0+1,r1) for c in range(c0+1,c1)
                 if grid[r][c] == color]
        if cells:
            motif = cells
            break
    # Remove the nonmatching-size frames.
    for color, (r0,r1,c0,c1) in boxes.items():
        if color not in group:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    if out[r][c] == color:
                        out[r][c] = 0
    # Replicate the interior motif in each member, using that frame's color.
    if motif:
        for color, (r0,r1,c0,c1) in group.items():
            for dr,dc in motif:
                out[r0+dr][c0+dc] = color
    return out
